// Generated by scripts/generate-workflow-blueprints.ts (extra questions); edit the specs there and re-run rather than editing by hand.
import { o, s, type QuestionSet } from "@/lib/interview-questions";

const bank: QuestionSet = {
  subjective: [
    s(5, "Walk me through this invoice extraction and approval workflow end to end.", "A Gmail Trigger watches the accounts-payable label and downloads PDF attachments. A hash of the file plus the message ID is checked against a Postgres ledger. Extract From File turns the PDF into text, and scanned images go to a separate OCR path. The Information Extractor, using an OpenAI-compatible chat model pointed at Vercel AI Gateway, returns a fixed JSON schema. A Code node recomputes totals, checks formats and looks for duplicates. An IF node sends failures to a Slack exceptions channel. Clean invoices go to the manager with a form resume link, and a Wait node pauses the execution. Once approved, the bill is posted with an idempotency key and retries, appended to Google Sheets and marked posted in the ledger. An Error Trigger workflow alerts on failures. The model extracts, code decides and a human approves."),
    s(4, "Why give the Information Extractor a fixed JSON schema instead of asking the model to describe the invoice in its own words?", "Every downstream node depends on predictable field names and types. The Code node can only recompute totals if line items arrive as an array with quantities and amounts, and the IF node can only detect missing fields if the schema says what should be present. Free text would need its own parsing step and would vary from run to run. A schema also makes evaluation possible, because you can compare vendor, GSTIN, invoice number and totals field by field against a labelled set. I would also tell the model to return null for anything it cannot find rather than guess, so gaps become visible exceptions instead of plausible-looking wrong values."),
    s(4, "Why route model calls through Vercel AI Gateway instead of plugging a provider key straight into n8n?", "The chat model sub-node is an OpenAI-compatible node with base URL https://ai-gateway.vercel.sh/v1 and an AI Gateway API key. One credential reaches many providers, so switching from \"openai/gpt-5\" to \"anthropic/claude-sonnet-4.5\" is a change to the model name, not a new integration. The gateway also gives fallbacks when a provider has problems, spend tracking per workload, and no provider keys stored in n8n. The trade-off is one more dependency in the request path. I cover that with retry-on-fail on the extractor and the Error Trigger workflow, so a gateway outage gives a retryable failed execution, never a silently wrong invoice."),
    s(4, "How do you handle a scanned invoice that has no text layer?", "Extract From File returns little or no usable text for a scanned image. Right after extraction I check the text length and whether it contains invoice-like content such as digits and currency markers. If it fails that check, the item goes to a separate OCR path instead of the extractor. Otherwise the model would get almost nothing and might invent a vendor or total. The OCR output then goes through the same Information Extractor, the same Code node checks and the same approval, so there is no weaker path. OCR text is noisier, so I tag those invoices in the ledger. That lets us track their exception rate separately and add extra review if it turns out to be higher."),
    s(4, "What does the Postgres ledger table look like?", "There is one row per invoice document. Columns: an internal ID, file hash, Gmail message ID, normalised vendor identifier such as GSTIN, normalised invoice number, n8n execution ID, status, exception reasons, approver, approved timestamp, posted timestamp, the accounting system's bill ID and the idempotency key. Status moves through received, extracted, exception, awaiting approval, approved or rejected, posted, and failed. A unique constraint on file hash, and another on vendor plus invoice number, enforce deduplication in the database itself. Updates are conditional, for example changing status to posted only where it is currently approved, so illegal transitions fail instead of corrupting state."),
    s(3, "Why check both the file hash and the message ID, and what does each one catch?", "They catch different kinds of repeats. The message ID catches the same email being seen again, for example after a trigger re-poll or a reprocessing attempt. The file hash catches the same PDF arriving in a different email, such as a vendor reminder or a colleague forwarding it to the AP inbox. Neither catches a re-issued invoice with different bytes but the same content. That is why the Code node also looks up vendor plus invoice number after extraction. These layers are cheap to run, and each closes a gap the others leave. The idempotency key at posting time is the final safeguard."),
    s(3, "How does the Code node apply a rounding tolerance when it checks totals?", "Vendors round differently. Some compute tax per line and others on the subtotal, and some round each line before summing. Requiring exact equality would flood the exceptions channel. I convert every amount to integer minor units, such as paise, to avoid floating-point drift. Then I sum line items and compare with the subtotal, and add tax and compare with the total. Each comparison allows a small tolerance set in configuration and agreed with finance, not hard-coded by a developer. Anything outside the tolerance fails with a reason that shows expected and actual values. The tolerance only absorbs rounding. It must never hide a missing line or a wrong tax rate."),
    s(3, "What checks would you run on a GSTIN?", "A GSTIN is 15 characters. The first two are a state code, the next ten follow the PAN format, then there is an entity code, a character that is normally Z, and a final checksum character. The Code node checks the pattern and recomputes the checksum, which catches most OCR or extraction slips such as a swapped digit. A valid format does not prove the supplier is registered or is who they claim, so I also match the GSTIN against a vendor master. An unknown or mismatched GSTIN goes to exceptions. That also helps against fake invoices that use a real vendor's name with someone else's tax ID."),
    s(3, "What goes into the Slack exceptions message, and how does an exception get resolved?", "The message names the vendor, invoice number and amount, then lists every failed check in plain language, such as \"line items sum differs from subtotal\" with both numbers. It also links to the n8n execution and the original email. The ledger row is set to exception with the same reasons. To resolve it, finance corrects the data or asks the vendor for a fixed invoice, then triggers a reprocess sub-workflow. That sub-workflow sends the corrected record back through the Code node checks and the normal approval. There is no override that skips validation, because that would break the rule that only checked, approved invoices are posted."),
    s(4, "How would you scale this workflow for month-end spikes?", "Run n8n in queue mode. The main instance handles triggers and webhooks, Redis holds the job queue, and several workers run executions in parallel, with Postgres as the n8n database. You add workers when backlog grows. Waiting executions do not tie up a worker while they wait for approval, so the human step does not block throughput. The real limits are usually downstream: gateway and provider rate limits, OCR throughput and the accounting API's rate limits. So I cap per-worker concurrency, use Loop Over Items to batch large attachment sets, and rely on retry-on-fail with backoff for throttling responses. The ledger's unique constraints keep parallel workers from creating duplicates."),
    s(3, "How would you estimate capacity and cost for this workflow without guessing numbers?", "Start from measured inputs: invoices per day, peak-day multiple at month end, pages per invoice and the share of scanned PDFs. Execution logs give per-step durations. Automated time is usually dominated by OCR and the model call, and the approval wait is human time that does not hold a worker. Workers needed is roughly peak arrivals times automated processing time divided by per-worker concurrency, plus headroom. For cost, multiply tokens per invoice by the model's current price, and check it against Vercel AI Gateway spend tracking. I would run a pilot on a real week of invoices and use the measured numbers rather than quoting figures."),
    s(5, "The accounting API times out, but it actually created the bill. What happens on retry?", "This is why the posting node uses an idempotency key built from vendor and invoice number. Retry-on-fail resends the same request with the same key, so an accounting system that supports idempotency returns the existing bill instead of creating a second one. If the API has no idempotency support, I search for an existing bill by vendor and invoice number before creating one. Either way, the ledger moves to posted only once we have a bill ID back. A timeout is never treated as a failure that justifies a fresh create without that check. Both layers exist because a timeout does not tell you whether the bill was created."),
    s(4, "What if the Google Sheets append fails after the bill was posted to accounting?", "The accounting system is the record of truth for bills, and the Sheets register is a reporting copy. A Sheets failure must never lead to re-posting. Because of the idempotency key, retrying the whole execution would not double-post anyway, but the better fix is to retry from the Sheets node. The Error Trigger workflow alerts Slack with the execution link so finance can do that. I also record the bill ID in the ledger as soon as posting succeeds, so the posted state is never lost. A periodic reconciliation compares the ledger with the sheet and backfills missing rows."),
    s(4, "How do you secure the manager's form resume link?", "The resume URL is unique to the waiting execution, so I treat it as a secret. It goes only to the right approver by Slack direct message or email, never to a shared channel. The Wait node's time limit means it stops working after the deadline, and once a decision is submitted the execution moves on, so the link cannot approve twice. Because anyone holding the link could submit the form, I also record and verify approver identity. Where possible I put authentication in front of the approval, and the decision is logged in the ledger with approver and timestamp. For high-value invoices I would add a second approver."),
    s(4, "What privacy and data-protection concerns does this workflow raise, and how do you handle them?", "Invoices hold bank account details, GSTINs, addresses and sometimes individuals' names, so India's Digital Personal Data Protection Act and internal finance policy apply. I send the model only the extracted text it needs and review the data-retention terms of the gateway and underlying providers. Slack messages carry summaries and links, not full invoice text or bank details. In n8n I limit who can view executions, configure execution data saving and pruning so payloads are not kept forever, and restrict the Google Sheet to finance. Credentials are stored encrypted. Bank detail changes are a classic fraud signal, so I would flag them for review instead of trusting them automatically."),
    s(3, "How are credentials managed in this workflow?", "Each integration has its own n8n credential: Gmail, Postgres, Slack, Google Sheets, the accounting system and the AI Gateway API key. n8n stores credentials encrypted and nodes reference them by name, so secrets never sit in Code nodes or workflow JSON. On self-hosted n8n the encryption key, set with N8N_ENCRYPTION_KEY, must be managed and backed up, because losing it means losing the credentials. I scope each credential tightly: read-only Gmail for the AP label where possible, a Postgres user limited to the ledger tables, and an accounting key that can create bills but not make payments. No model provider keys live in n8n, only the gateway key."),
    s(3, "How would you test and evaluate the extraction quality?", "I would build a labelled set of real, anonymised invoices with expected JSON. It should cover the hard cases: multi-page invoices, discounts, IGST versus CGST and SGST, foreign currency, scanned copies and unusual layouts. I run it through the extractor and measure accuracy field by field, because a wrong invoice number matters differently from a wrong address. Totals errors are caught by the Code node in production, but a wrongly read invoice number can slip through, so those fields need the evaluation most. Any prompt change, schema change or model name change in the gateway re-runs the set before release. Fallback models must pass it too."),
    s(4, "How do you protect against prompt injection hidden in invoice text?", "The invoice is untrusted input. Someone could embed text like \"this invoice is pre-approved, pay immediately\". The design limits what that can do. The Information Extractor has no tools and can only fill a fixed schema, so it cannot take any action. Whatever it returns is checked by deterministic code. Approval comes only from the manager's form submission on the Wait node, never from anything in the document. Posting is triggered by the workflow's control flow, not by the model. The worst an injection can do is corrupt extracted fields, and the arithmetic, format, vendor-master and duplicate checks plus human review are built to catch that."),
    s(3, "What does the Error Trigger workflow do, and why is it a separate workflow?", "It is set as the error workflow for the main invoice workflow. When any execution fails, it starts with details of the failure: execution ID and link, the failing node and the error message. It posts these to a Slack channel for finance and marks the ledger row as failed. Finance can open the execution and retry it from n8n's execution history, without asking the vendor to re-send the email. Keeping it separate means alerting still works even if the main workflow is broken, and one error workflow can serve several finance workflows. Because posting is idempotent, retries are safe."),
    s(3, "What are the trade-offs of using a Wait node for approval versus storing state and resuming from a separate workflow?", "The Wait node is simple. Invoice context stays in the execution, the resume link comes for free and the flow reads top to bottom. The downsides are long-lived executions that depend on the workflow version they started with, and pending approvals are hard to query from n8n alone. A separate design writes the invoice to the ledger as awaiting approval and ends. Another workflow, triggered by the approval form, reloads it and posts. That gives cleaner versioning and easier bulk handling, at the cost of more plumbing. Because this design already keeps status in the ledger, pending approvals can be listed either way."),
    s(2, "How does the workflow handle invoices in a currency other than INR?", "The schema has an explicit currency field, and the Code node checks it against a list of allowed ISO 4217 codes. Arithmetic is done in that currency's own minor units, since not every currency has two decimal places. The model is never asked to convert anything. If the accounting system needs a base-currency amount, that comes from the accounting system or a defined rate source, not from the LLM. An unexpected currency, a mismatch between symbols and the extracted code, or a vendor who normally bills in a different currency goes to the exceptions channel, because those cases often mean an extraction error or something unusual."),
    s(3, "How would you pick a model for the Information Extractor, and how do fallbacks fit in?", "I choose by measured results on the labelled invoice set: field-level accuracy first, then latency and cost. Through Vercel AI Gateway, candidates such as \"openai/gpt-5\" or \"anthropic/claude-sonnet-4.5\" differ only by model name, so comparing them is cheap. I configure a fallback in the gateway so a provider outage does not stop intake. The fallback must also pass the same evaluation, because it fills the same schema and feeds the same checks. I pin the model choice in configuration and re-run the evaluation before any change, so quality does not drift silently. Gateway spend tracking shows the cost impact."),
    s(3, "A vendor sends a revised invoice or a credit note with the same invoice number. How should the workflow behave?", "The vendor plus invoice number check in the Code node flags it as a duplicate. It goes to exceptions and is never posted automatically. Overwriting or posting a second bill would break the no-duplicates rule. Finance decides whether it replaces an unposted original or needs a credit note against a posted bill. I would extend the schema with a document-type field so credit notes are identified explicitly and routed to their own handling, because they reduce payables instead of adding to them. The ledger keeps both documents linked, so the audit trail shows what happened and who decided."),
    s(3, "How would you extend the approval step for amount thresholds or multiple approvers?", "After validation, a Switch node routes on total, vendor category or cost centre, using thresholds from a configuration table rather than hard-coded values. Low-value invoices need one approver. Higher values pass through sequential Wait nodes, each sending its own resume link to the next approver in a mapping table. Each decision is recorded in the ledger with approver and timestamp, and a rejection at any stage ends the flow without posting. I would also block self-approval by checking that the approver is not the person who requested the purchase. Every route still ends at the same idempotent posting node."),
    s(3, "How would you monitor this workflow in production?", "I combine n8n execution logs with the ledger. From the ledger I track counts by status, exception rate by reason, time from receipt to posting and how long invoices sit awaiting approval. A growing approval backlog near month end is an operational risk that needs alerts. The Error Trigger workflow covers outright failures. Gateway spend tracking shows model cost and catches runaway usage. I review exception reasons regularly, because a spike in arithmetic failures for one vendor usually means a new layout the extractor misreads. Periodic reconciliation between the ledger, the accounting system and the Sheets register confirms all three agree."),
    s(2, "Why keep a Google Sheets AP register when the bill is already in the accounting system?", "Finance teams often want a quick, shareable view of what was processed, who approved it and when, without opening the accounting system. A sheet gives that cheaply. It is a reporting copy, not a source of truth, which brings risks: people can edit or delete rows, and sharing can spread too widely. So I protect the sheet, limit access to finance and never read from it to make posting decisions. Those decisions use the Postgres ledger and the accounting system. If the sheet drifts or is damaged, it can be rebuilt from the ledger."),
    s(4, "In queue mode, two workers process the same invoice at the same moment. How do you stop both from continuing?", "A read-then-write check is not enough, because both workers can read \"not seen\" before either writes. I use the database to decide. The first step inserts the ledger row with the file hash and message ID under a unique constraint, using insert-on-conflict-do-nothing and returning the row. Only the worker whose insert succeeds continues, and the other stops. The vendor plus invoice number constraint covers the case after extraction in the same way. As a final layer, the idempotency key on the accounting call means even an unexpected race could not create two bills."),
    s(3, "What happens to invoices waiting for approval if n8n restarts or is upgraded?", "Waiting executions are stored in the n8n database, not held only in memory. After a restart they still resume when the form is submitted or the time limit is reached. That makes the database critical: use durable Postgres with backups, not an ephemeral store. The bigger risk is changing the workflow while executions are waiting, because a resumed execution may reach nodes that were renamed or changed. So I make backward-compatible edits, or let pending approvals drain before structural changes. Because the ledger tracks every awaiting-approval invoice, any execution that cannot resume can be found and reprocessed."),
    s(4, "How do you make sure a rejected invoice cannot be posted later?", "On rejection, the workflow sets the ledger row to rejected with the approver, reason and timestamp, and notifies AP so they can contact the vendor. The Wait node has resumed, so that resume link cannot be used again. The posting step also checks the ledger immediately before calling the accounting API and posts only if the status is approved. The transition to posted is a conditional update from approved. If someone later reprocesses the same email or PDF, the duplicate checks find the existing rejected row, and the invoice goes to exceptions instead of quietly getting a second approval."),
    s(3, "How would you reprocess an invoice after an exception has been fixed?", "I would not rerun the whole email intake, because the dedupe check would correctly block it. Instead, a reprocess sub-workflow called with Execute Workflow takes the existing ledger row and the corrected data. It re-enters at the Code node validation, so the arithmetic, format and duplicate checks all run again on the corrected values. If they pass, the invoice goes through the same approval and the same idempotent posting. The ledger row is reused, with a note of what was changed and by whom, so the audit trail stays complete. There is no path that skips validation or approval."),
  ],
  objective: [
    o(4, "Which node starts this workflow when a new invoice email arrives?", ["Schedule Trigger polling Google Sheets","Gmail Trigger filtered by the accounts-payable label","Chat Trigger","Error Trigger"], 1, "Step 1 uses a Gmail Trigger that watches the AP inbox by label and downloads PDF attachments."),
    o(5, "At intake, what is checked against the Postgres ledger to avoid processing the same invoice twice?", ["Only the sender's email address","The PDF file name","A hash of the file plus the Gmail message ID","The invoice total"], 2, "The blueprint combines a file hash with the message ID, which catches both repeated emails and the same PDF arriving in a different email."),
    o(4, "What should happen to a scanned PDF that has no text layer?", ["It is routed to a separate OCR path","The model guesses the fields from the file name","It is posted with blank fields","It is deleted silently"], 0, "Scanned images are sent to OCR instead of letting the model guess from missing text."),
    o(3, "Which node turns the PDF attachment into text before extraction?", ["Merge","Set/Edit Fields","Text Classifier","Extract From File"], 3, "Step 2 uses Extract From File to get the PDF's text layer."),
    o(3, "Which model name follows the format used by Vercel AI Gateway?", ["claude-sonnet@anthropic","anthropic/claude-sonnet-4.5","gpt5.openai.com","model:sonnet:4.5"], 1, "Gateway models are named provider/model, such as \"anthropic/claude-sonnet-4.5\" or \"openai/gpt-5\"."),
    o(4, "What is a key security benefit of routing model calls through Vercel AI Gateway in this design?", ["Invoices no longer need validation","The Wait node is no longer needed","No provider API keys are stored in n8n; one gateway key is used","It replaces Postgres as the ledger"], 2, "A single AI Gateway API key reaches many providers, so provider keys stay out of n8n."),
    o(5, "What is the posting idempotency key built from?", ["Vendor and invoice number","The n8n execution ID only","The current timestamp","The approver's email"], 0, "Vendor plus invoice number identifies the bill the same way on every retry, so the accounting system can reject or merge duplicates."),
    o(4, "Why is retry-on-fail safe to enable on the posting node?", ["The accounting API never fails","Retries are limited to one attempt","n8n deletes the earlier request automatically","Every retry sends the same idempotency key, so a duplicate bill is not created"], 3, "Idempotency makes a repeated request return the existing bill instead of creating a new one."),
    o(3, "Where does an invoice with failed checks or missing fields go?", ["Straight to the accounting system with a warning","To a Slack exceptions channel, with the reasons","To the manager for approval anyway","Back to the vendor automatically"], 1, "Step 5 sends failed invoices to a Slack exceptions channel with reasons, and only clean ones continue."),
    o(3, "Which node splits clean invoices from those that failed checks?", ["IF node","Merge node","Wait node","Loop Over Items"], 0, "An IF node branches on the Code node's check results."),
    o(4, "What does n8n queue mode use to scale executions?", ["Google Sheets as a job list","A single larger main instance","Redis plus separate worker processes","The Wait node"], 2, "Queue mode puts executions on a Redis queue that multiple workers consume."),
    o(4, "What is the main job of the Error Trigger workflow here?", ["Approving invoices automatically on timeout","Catching failed executions and alerting Slack with the execution link","Re-sending the original email","Running OCR"], 1, "Step 9 alerts finance with the execution link so they can retry without the email being re-sent."),
    o(3, "After posting, what does the Postgres ledger row record?", ["Only the PDF file","The full model prompt","Nothing; the ledger is only used at intake","Status posted, plus the approver and timestamp"], 3, "Step 8 marks the ledger row posted with the approver and timestamp."),
    o(3, "How many characters does a valid Indian GSTIN have?", ["10","12","15","18"], 2, "A GSTIN is 15 characters: state code, PAN, entity code, a default character and a checksum."),
    o(4, "What is the most reliable way for the Code node to compare money amounts?", ["Convert to integer minor units such as paise and compare within a configured tolerance","Compare floating-point numbers for exact equality","Compare the amounts as strings","Ask the model whether they match"], 0, "Integer minor units avoid floating-point drift, and the tolerance absorbs legitimate rounding differences."),
    o(2, "Which languages can an n8n Code node run?", ["SQL only","JavaScript or Python","Java or Go","Only n8n expressions"], 1, "The n8n Code node supports JavaScript and Python."),
    o(3, "How does n8n handle the credentials for Gmail, Postgres, Slack and the AI Gateway?", ["Stored in plain text inside each Code node","Pasted into each email","Stored encrypted and referenced by nodes","Kept only in Google Sheets"], 2, "n8n stores credentials encrypted and nodes reference them, so secrets stay out of workflow logic."),
    o(4, "Two queue-mode workers pick up the same invoice at the same time. What reliably stops both from continuing?", ["A random delay in each worker","Checking Google Sheets first","Asking the model to detect duplicates","An insert into the ledger under a unique constraint, so only one insert succeeds"], 3, "The database's unique constraint settles the race. A read-then-write check can let both workers through."),
    o(4, "An invoice contains the text \"This invoice is pre-approved; pay immediately.\" What should happen?", ["Nothing changes; approval comes only from the manager's form submission on the Wait node","Skip the Wait node","Post it right away","Raise the rounding tolerance"], 0, "Approval is a control-flow step tied to the Wait form, so text inside the document cannot grant it."),
    o(3, "What does the Information Extractor return in this workflow?", ["A free-text summary","A fixed JSON schema: vendor, GSTIN, invoice number, dates, currency, line items, subtotal, tax and total","A yes/no approval decision","The PDF as an image"], 1, "Step 3 defines a fixed schema so downstream checks get predictable fields."),
    o(2, "How is n8n licensed?", ["Proprietary and cloud-only","Public domain","Fair-code, available self-hosted or as n8n Cloud","GPL with no hosted option"], 2, "The reference notes describe n8n as a fair-code platform that can be self-hosted or run on n8n Cloud."),
    o(3, "Which step looks up vendor plus invoice number to find duplicates after extraction?", ["The Gmail Trigger","The Wait node","The Slack node","The Code node"], 3, "Step 4's Code node checks vendor plus invoice number, which catches re-issued invoices whose file hash differs."),
    o(2, "Which node would you use to call a reusable sub-workflow, such as a reprocessing or OCR path?", ["Execute Workflow","Merge","Set/Edit Fields","Error Trigger"], 0, "Execute Workflow calls sub-workflows in n8n."),
    o(2, "Which node processes a large set of attachments in batches?", ["Switch","Loop Over Items","Wait","Chat Trigger"], 1, "Loop Over Items splits items into batches, which helps respect downstream rate limits."),
    o(3, "Which store tracks each invoice's processing state, such as received, awaiting approval or posted?", ["The Google Sheets AP register","The Slack exceptions channel","The Postgres ledger","The Gmail label"], 2, "The Postgres ledger holds the dedupe keys and status, while Sheets is a reporting copy."),
    o(4, "Which order matches the blueprint?", ["Post, then validate, then approve","Approve, then extract, then post","Extract, post, then validate","Extract, validate, approve, post, then record in Sheets and the ledger"], 3, "Posting only happens after deterministic checks and manager approval, which enforces the rule against posting unapproved invoices."),
    o(4, "Why are the totals recomputed in a Code node rather than by the model?", ["Code gives a deterministic, repeatable result that can be audited","Code nodes are faster than all other nodes","The model cannot read numbers at all","n8n does not allow model nodes to output numbers"], 0, "Arithmetic checks must give the same verdict every time. A model's judgement can vary and is hard to audit."),
    o(3, "The extractor returns null for GSTIN. What should the workflow do?", ["Fill in the GSTIN from the vendor's name using the model","Send the invoice to the exceptions channel as a missing field","Post it and fix it later","Use the previous invoice's GSTIN"], 1, "Missing fields fail the checks and go to exceptions. They are never guessed."),
    o(3, "A failed execution is caught by the Error Trigger. What does finance not need to do to retry it?", ["Open the execution link","Check the error message","Ask the vendor to re-send the invoice email","Confirm the ledger status"], 2, "The blueprint is designed so finance can retry from the execution link without the email being re-sent."),
    o(4, "A vendor re-sends the same invoice as a newly generated PDF, so the bytes and hash differ. Which check catches it?", ["The file hash check","The Gmail label filter","The rounding tolerance","The vendor plus invoice number duplicate lookup in the Code node"], 3, "A different file gives a different hash, but the business identifiers are the same, so the vendor plus invoice number check catches it."),
  ],
};
export default bank;
